## 3. Result-Generation Logic (form data → recommendation)

Source: `client/src/lib/pituitaryAdenomaLogic.ts`

```typescript
/**
 * Pituitary Adenoma Clinical Logic Engine
 *
 * Based on:
 * - CNS 2025 Systematic Review and Evidence-Based Guidelines for Functioning Pituitary Adenomas
 *   (Surgery, Radiosurgery, Medical Perioperative Management, Imaging — Neurosurgery 97(3S), 2025)
 * - Endocrine Society Clinical Practice Guidelines (Acromegaly 2014, Cushing 2015, Prolactinoma 2011)
 * - AAES/AACE/ENETS Pituitary Tumor Management Consensus
 *
 * PMIDs: 40815129, 40815132, 40815128, 40815142
 */

// ─── Types ────────────────────────────────────────────────────────────────────

export type TumorType =
  | "prolactinoma"
  | "acromegaly_gh"
  | "cushings_acth"
  | "tshoma"
  | "nonfunctioning";

export type TumorSize = "microadenoma" | "macroadenoma" | "giant"; // <10mm, 10-40mm, >40mm

export type CavernousSinusInvasion = "none" | "unilateral" | "bilateral";

export type ProlactinLevel =
  | "mildly_elevated" // <200 ng/mL
  | "moderately_elevated" // 200-500 ng/mL
  | "markedly_elevated"; // >500 ng/mL

export type PrimaryRecommendation =
  | "medical_therapy_first"
  | "surgery_first"
  | "radiosurgery_adjuvant"
  | "multidisciplinary_evaluation"
  | "observation_with_imaging"
  | "urgent_surgery";

export interface PituitaryAdenomaInput {
  // Tumor characteristics
  tumorType: TumorType;
  tumorSize: TumorSize;
  tumorSizeMm: number;
  cavernousSinusInvasion: CavernousSinusInvasion;
  suprasellarExtension: boolean;
  cysticComponent: boolean;

  // Functional status
  visualFieldDefect: boolean;
  cranialNervePalsy: boolean;
  hypopituitarism: boolean;
  pituitaryApoplexy: boolean;

  // Hormone-specific
  prolactinLevelNgMl?: number; // for prolactinoma
  igf1Elevated?: boolean; // for acromegaly
  lateNightSalivaryCortisolElevated?: boolean; // for Cushing's
  tshElevated?: boolean; // for TSHoma

  // Treatment history
  priorSurgery: boolean;
  priorRadiation: boolean;
  priorMedicalTherapy: boolean;
  medicalTherapyResponse?: "complete" | "partial" | "none";

  // Patient factors
  ageYears: number;
  pregnancyDesired: boolean;
  surgicalRisk: "low" | "moderate" | "high";
  preferMinimallyInvasive: boolean;

  // Postoperative (if applicable)
  postopCortisolUgDl?: number; // for Cushing's remission assessment
  hoursPostSurgery?: number;
}

export interface PituitaryAdenomaRecommendation {
  primaryRecommendation: PrimaryRecommendation;
  recommendationTitle: string;
  rationale: string;
  evidenceLevel: "A" | "B" | "C" | "Expert";
  guidelineSource: string;

  // Treatment pathway details
  surgicalApproach?: string;
  medicalOptions?: string[];
  radiosurgeryIndication?: string;

  // Perioperative management
  perioperativeNotes: string[];
  postopMonitoring: string[];

  // Imaging follow-up
  imagingFollowUp: string[];

  // Warnings and flags
  urgentFlags: string[];
  warnings: string[];

  // Next steps
  nextSteps: string[];

  // References
  references: Array<{ citation: string; pmid?: string; url?: string }>;
}

// ─── Core Logic ──────────────────────────────────────────────────────────────

export function assessPituitaryAdenoma(
  input: PituitaryAdenomaInput
): PituitaryAdenomaRecommendation {
  const urgentFlags: string[] = [];
  const warnings: string[] = [];
  const perioperativeNotes: string[] = [];
  const postopMonitoring: string[] = [];
  const imagingFollowUp: string[] = [];
  const nextSteps: string[] = [];

  // ── Urgent flags ──────────────────────────────────────────────────────────
  if (input.pituitaryApoplexy) {
    urgentFlags.push(
      "PITUITARY APOPLEXY: Urgent neurosurgical evaluation required. Consider emergent decompression if visual compromise or altered consciousness."
    );
  }
  if (input.visualFieldDefect && !input.pituitaryApoplexy) {
    urgentFlags.push(
      "Visual field defect detected: Expedited surgical evaluation recommended to prevent permanent vision loss (chiasmal compression)."
    );
  }
  if (input.cranialNervePalsy) {
    urgentFlags.push(
      "Cranial nerve palsy present: Indicates cavernous sinus involvement. Urgent multidisciplinary evaluation."
    );
  }

  // ── Prolactinoma pathway ──────────────────────────────────────────────────
  if (input.tumorType === "prolactinoma") {
    const prolactin = input.prolactinLevelNgMl ?? 0;

    // Pregnancy considerations
    if (input.pregnancyDesired && input.tumorSize === "macroadenoma") {
      warnings.push(
        "Pregnancy desired with macroprolactinoma: Dopamine agonist (cabergoline preferred) should achieve tumor control before conception. Monitor closely during pregnancy."
      );
    }

    // Medical therapy is first-line for prolactinomas
    if (!input.visualFieldDefect && !input.pituitaryApoplexy) {
      const rec: PituitaryAdenomaRecommendation = {
        primaryRecommendation: "medical_therapy_first",
        recommendationTitle: "Dopamine Agonist Therapy — First-Line",
        rationale:
          "CNS 2025 guidelines recommend medical management (dopamine agonist) over surgery as primary treatment for prolactin-secreting microadenomas and most macroadenomas. Cabergoline achieves normoprolactinemia in >80% of patients and tumor shrinkage in 70–80% of macroadenomas.",
        evidenceLevel: "C",
        guidelineSource:
          "CNS 2025 Functioning Pituitary Adenoma Guidelines (Neurosurgery 97(3S), 2025; PMID 40815128)",
        medicalOptions: [
          "Cabergoline 0.25–3.5 mg twice weekly (preferred — higher efficacy, better tolerability than bromocriptine)",
          "Bromocriptine 2.5–15 mg/day (alternative, especially in pregnancy — more safety data)",
          "Target: normoprolactinemia + tumor size reduction",
          "Reassess at 3 months; MRI at 6 months if macroadenoma",
        ],
        perioperativeNotes: [
          "Fluid restriction after trans-sphenoidal surgery is suggested to prevent delayed hyponatremia (CNS 2025, Class III).",
          "Postoperative serum sodium monitoring for 7–10 days recommended.",
        ],
        postopMonitoring: [
          "Prolactin level at 6 weeks post-treatment initiation",
          "MRI at 6 months if macroadenoma to assess tumor response",
          "Annual MRI if stable; every 2 years if in remission",
        ],
        imagingFollowUp: [
          "MRI pituitary with gadolinium: baseline, then 6 months after treatment initiation",
          "Annual MRI for macroadenomas until stable × 2 years, then every 2 years",
          "Microadenoma on stable DA therapy: MRI every 2 years",
        ],
        urgentFlags,
        warnings,
        nextSteps: [
          "Initiate cabergoline at low dose (0.25 mg twice weekly), titrate to normoprolactinemia",
          "Check prolactin level at 4–6 weeks",
          "Obtain baseline MRI pituitary with gadolinium if not already done",
          "Refer to endocrinology for ongoing management",
          "Discuss fertility implications if relevant",
          prolactin > 500
            ? "Prolactin >500 ng/mL: strongly suggests macroprolactinoma — ensure MRI confirms diagnosis"
            : "",
        ].filter(Boolean),
        references: getPituitaryReferences(),
      };
      return rec;
    }
  }

  // ── Acromegaly (GH-secreting) pathway ────────────────────────────────────
  if (input.tumorType === "acromegaly_gh") {
    // Surgery is first-line for GH microadenomas
    if (input.tumorSize === "microadenoma") {
      perioperativeNotes.push(
        "Preoperative somatostatin analogs are NOT routinely recommended for GH-secreting microadenomas (CNS 2025, Class III)."
      );
      perioperativeNotes.push(
        "Fluid restriction post-surgery suggested to prevent delayed hyponatremia."
      );
      postopMonitoring.push(
        "IGF-1 at 12 weeks postoperatively to assess biochemical remission"
      );
      postopMonitoring.push(
        "Oral glucose tolerance test (OGTT) with GH at 3 months"
      );
      postopMonitoring.push(
        "MRI at 3 months postoperatively to assess extent of resection"
      );

      return {
        primaryRecommendation: "surgery_first",
        recommendationTitle:
          "Endoscopic Trans-Sphenoidal Surgery — First-Line for GH Microadenoma",
        rationale:
          "CNS 2025 guidelines recommend surgery over medical management for GH-secreting microadenomas. Cure rates of 70–90% for microadenomas with experienced pituitary surgeons. Endoscopic technique may offer superior outcomes for macroadenomas without cavernous sinus invasion.",
        evidenceLevel: "C",
        guidelineSource:
          "CNS 2025 Functioning Pituitary Adenoma Guidelines (PMID 40815132)",
        surgicalApproach:
          "Endoscopic endonasal trans-sphenoidal surgery (EETS) preferred. Microscopic approach acceptable alternative. Endoscopic technique may be superior for macroadenomas without cavernous sinus invasion (shorter operative time, higher EOR, better hormone remission rates).",
        perioperativeNotes,
        postopMonitoring,
        imagingFollowUp: [
          "MRI pituitary at 3 months postoperatively",
          "Annual MRI × 3 years, then every 2 years if stable",
          "MRI grading systems (Knosp grade) to predict postoperative biochemical control",
        ],
        urgentFlags,
        warnings: [
          ...warnings,
          input.cavernousSinusInvasion !== "none"
            ? `Cavernous sinus invasion (${input.cavernousSinusInvasion}): Reduces surgical cure rate significantly. Adjuvant medical therapy or radiosurgery likely required.`
            : "",
        ].filter(Boolean),
        nextSteps: [
          "Refer to experienced pituitary neurosurgeon (center with >50 pituitary cases/year)",
          "Preoperative endocrine evaluation: IGF-1, GH, cortisol, thyroid, gonadal axes",
          "Ophthalmology evaluation if suprasellar extension",
          "Cardiology evaluation (acromegaly-related cardiomyopathy)",
          "Postoperative: IGF-1 and OGTT-GH at 12 weeks",
          input.cavernousSinusInvasion !== "none"
            ? "Plan for adjuvant somatostatin analog (octreotide LAR or lanreotide) if residual disease"
            : "",
        ].filter(Boolean),
        references: getPituitaryReferences(),
      };
    }

    // GH macroadenoma
    perioperativeNotes.push(
      "Preoperative somatostatin analogs may be considered for large macroadenomas to reduce tumor vascularity and improve surgical conditions (not routinely recommended per CNS 2025)."
    );
    if (input.cavernousSinusInvasion === "bilateral") {
      warnings.push(
        "Bilateral cavernous sinus invasion: Surgical cure unlikely (<20%). Plan for multimodal therapy: surgery for debulking + somatostatin analog + radiosurgery."
      );
    }
  }

  // ── Cushing's disease (ACTH-secreting) pathway ───────────────────────────
  if (input.tumorType === "cushings_acth") {
    // Postoperative cortisol assessment
    if (
      input.postopCortisolUgDl !== undefined &&
      input.hoursPostSurgery !== undefined
    ) {
      if (
        input.postopCortisolUgDl < 2 &&
        input.hoursPostSurgery <= 72
      ) {
        return {
          primaryRecommendation: "surgery_first",
          recommendationTitle:
            "Biochemical Remission Confirmed — Glucocorticoid Replacement Required",
          rationale:
            "Postoperative serum cortisol <2 μg/dL within 72 hours is a strong predictor of remission (CNS 2025, Class III). Glucocorticoid replacement is required to prevent adrenal insufficiency.",
          evidenceLevel: "C",
          guidelineSource:
            "CNS 2025 Functioning Pituitary Adenoma Guidelines (PMID 40815128)",
          perioperativeNotes: [
            "Serum cortisol <2 μg/dL within ≤72 hours post-surgery = predictor of remission (CNS 2025).",
            "Initiate glucocorticoid replacement immediately (hydrocortisone 10–15 mg/m²/day in divided doses).",
            "Fluid restriction post-surgery to prevent delayed hyponatremia.",
          ],
          postopMonitoring: [
            "Morning cortisol at 6 weeks (off replacement) to confirm remission",
            "24-hour urinary free cortisol at 3 months",
            "Late-night salivary cortisol at 3 months",
            "MRI at 3 months",
            "Annual MRI × 5 years (high recurrence risk)",
          ],
          imagingFollowUp: [
            "MRI pituitary at 3 months postoperatively",
            "Annual MRI × 5 years (Cushing's recurrence rate 10–25% at 5 years)",
          ],
          urgentFlags,
          warnings: [
            ...warnings,
            "Adrenal insufficiency risk: Patient requires glucocorticoid replacement and stress-dosing education.",
          ],
          nextSteps: [
            "Initiate hydrocortisone replacement (10–15 mg/m²/day)",
            "Educate patient on sick-day dosing and adrenal crisis prevention",
            "Endocrinology follow-up at 6 weeks",
            "Morning cortisol off replacement at 6 weeks to confirm sustained remission",
          ],
          references: getPituitaryReferences(),
        };
      }
    }

    // Preoperative Cushing's
    perioperativeNotes.push(
      "BIPSS (bilateral inferior petrosal sinus sampling) is recommended if MRI is negative or equivocal to confirm pituitary source (CNS 2025, Class III)."
    );
    perioperativeNotes.push(
      "If ectopic ACTH syndrome suspected → CT abdomen/pelvis preferred over pituitary MRI (CNS 2025, Class III)."
    );
    if (input.tumorSize === "microadenoma") {
      warnings.push(
        "ACTH-secreting microadenoma: Insufficient evidence to favor surgery over medical management per CNS 2025. Surgery remains standard of care at experienced centers."
      );
    }
  }

  // ── TSHoma pathway ────────────────────────────────────────────────────────
  if (input.tumorType === "tshoma") {
    warnings.push(
      "TSH-secreting adenoma: Insufficient evidence to favor surgery over medical management per CNS 2025. Surgery is standard first-line at experienced centers."
    );
    perioperativeNotes.push(
      "Preoperative thyroid function normalization with somatostatin analogs or antithyroid drugs recommended to reduce surgical risk."
    );
  }

  // ── Recurrent/persistent disease → radiosurgery ──────────────────────────
  if (
    input.priorSurgery &&
    (input.medicalTherapyResponse === "none" ||
      input.medicalTherapyResponse === "partial")
  ) {
    return {
      primaryRecommendation: "radiosurgery_adjuvant",
      recommendationTitle:
        "Stereotactic Radiosurgery — Adjuvant for Recurrent/Persistent Disease",
      rationale:
        "CNS 2025 guidelines suggest SRS, hypofractionated SRS, fractionated RT, and conventional RT for progressive/recurrent functioning pituitary adenomas with improved radiographic control and variable hormonal reduction (Class III). Endocrine-suppressive medical therapy may be continued before SRS.",
      evidenceLevel: "C",
      guidelineSource:
        "CNS 2025 Functioning Pituitary Adenoma Guidelines — Radiosurgery (PMID 40815129)",
      radiosurgeryIndication:
        "Recurrent or persistent functioning pituitary adenoma after surgery with inadequate response to medical therapy.",
      perioperativeNotes: [
        "Endocrine-suppressive medical therapy may be continued before SRS (CNS 2025, Class III).",
        "Coordinate with radiation oncology for treatment planning.",
        "Minimum 3–6 month interval from surgery to SRS recommended.",
      ],
      postopMonitoring: [
        "Hormone levels at 3, 6, 12 months post-SRS",
        "MRI at 6 months post-SRS, then annually",
        "Hypopituitarism screening annually (GH, ACTH, TSH, LH/FSH axes)",
      ],
      imagingFollowUp: [
        "MRI at 6 months post-SRS",
        "Annual MRI × 5 years",
        "Long-term annual MRI (radiosurgery effect can take 2–5 years)",
      ],
      urgentFlags,
      warnings: [
        ...warnings,
        "Radiosurgery hormonal remission rates: 50–60% for Cushing's, 40–60% for acromegaly, 25–40% for prolactinoma at 5 years.",
        "Hypopituitarism risk post-SRS: 20–30% at 5 years.",
      ],
      nextSteps: [
        "Multidisciplinary tumor board review (neurosurgery, endocrinology, radiation oncology)",
        "Radiation oncology consultation for SRS planning",
        "Continue medical therapy (somatostatin analog, dopamine agonist, or steroidogenesis inhibitor) until SRS effect achieved",
        "Annual pituitary hormone panel",
      ],
      references: getPituitaryReferences(),
    };
  }

  // ── Default: surgery first for most functioning adenomas ─────────────────
  const isMacro =
    input.tumorSize === "macroadenoma" || input.tumorSize === "giant";
  const endoscopicSuperior =
    isMacro && input.cavernousSinusInvasion === "none";

  perioperativeNotes.push(
    "Fluid restriction after trans-sphenoidal surgery is suggested to prevent delayed hyponatremia (CNS 2025, Class III)."
  );
  perioperativeNotes.push(
    "Postoperative serum cortisol <2 μg/dL within ≤72 hours predicts remission in Cushing's disease."
  );
  if (input.hypopituitarism) {
    perioperativeNotes.push(
      "Preoperative hypopituitarism: Ensure cortisol replacement before surgery. Stress-dose steroids perioperatively."
    );
  }

  return {
    primaryRecommendation: "surgery_first",
    recommendationTitle: `Endoscopic Trans-Sphenoidal Surgery — Primary Treatment`,
    rationale: `Trans-sphenoidal surgery is the primary treatment for most functioning pituitary adenomas (except prolactinomas). ${
      endoscopicSuperior
        ? "Endoscopic technique may be superior to microscopic for macroadenomas without cavernous sinus invasion (shorter operative time, higher EOR, better hormone remission rates — CNS 2025, Class III)."
        : ""
    }`,
    evidenceLevel: "C",
    guidelineSource:
      "CNS 2025 Functioning Pituitary Adenoma Guidelines — Surgery (PMID 40815132)",
    surgicalApproach: endoscopicSuperior
      ? "Endoscopic endonasal trans-sphenoidal surgery (EETS) preferred for macroadenomas without cavernous sinus invasion."
      : "Endoscopic or microscopic trans-sphenoidal approach based on surgeon expertise and anatomy.",
    perioperativeNotes,
    postopMonitoring: [
      "Serum cortisol within 72 hours postoperatively (Cushing's disease)",
      "IGF-1 at 12 weeks (acromegaly)",
      "Prolactin at 6 weeks (prolactinoma)",
      "Full pituitary hormone panel at 6 weeks",
      "MRI at 3 months postoperatively",
    ],
    imagingFollowUp: [
      "MRI pituitary with gadolinium: baseline (if not done), then 3 months postoperatively",
      "Annual MRI × 3 years, then every 2 years if stable",
      "MRI grading systems (Knosp grade) recommended to predict postoperative biochemical control (CNS 2025, Class III)",
    ],
    urgentFlags,
    warnings: [
      ...warnings,
      input.cavernousSinusInvasion !== "none"
        ? `Cavernous sinus invasion (${input.cavernousSinusInvasion}): Surgical cure rate reduced. Plan for adjuvant medical therapy or radiosurgery.`
        : "",
      isMacro
        ? "Macroadenoma: Ophthalmology evaluation required preoperatively for visual field assessment."
        : "",
    ].filter(Boolean),
    nextSteps: [
      "Refer to experienced pituitary neurosurgeon (high-volume center)",
      "Preoperative endocrine evaluation: full pituitary hormone panel",
      "Ophthalmology evaluation with formal visual fields if suprasellar extension",
      "Anesthesia evaluation (acromegaly: difficult airway; Cushing's: metabolic optimization)",
      "Postoperative endocrinology follow-up at 6 weeks",
    ],
    references: getPituitaryReferences(),
  };
}

// ─── Helper Functions ─────────────────────────────────────────────────────────

function getPituitaryReferences() {
  return [
    {
      citation:
        "Turin CG et al. CNS Systematic Review and Evidence-Based Guidelines for Medical Perioperative Management for Functioning Pituitary Adenomas. Neurosurgery. 2025;97(3S):S1-S14.",
      pmid: "40815128",
    },
    {
      citation:
        "Lillehei KO et al. CNS Systematic Review and Evidence-Based Guidelines for the Role of Surgery for Functioning Pituitary Adenomas. Neurosurgery. 2025;97(3S):24-35.",
      pmid: "40815132",
    },
    {
      citation:
        "Green S et al. CNS Systematic Review and Evidence-Based Guidelines for the Role of Radiosurgery for Functioning Pituitary Adenomas. Neurosurgery. 2025;97(3S):S36-S43.",
      pmid: "40815129",
    },
    {
      citation:
        "Junn JC et al. CNS Systematic Review and Evidence-Based Guidelines for the Role of Imaging for Functioning Pituitary Adenomas. Neurosurgery. 2025;97(3S):S15-S23.",
      pmid: "40815142",
    },
    {
      citation:
        "Katznelson L et al. Acromegaly: An Endocrine Society Clinical Practice Guideline. J Clin Endocrinol Metab. 2014;99(11):3933-3951.",
      pmid: "25356808",
    },
    {
      citation:
        "Nieman LK et al. Treatment of Cushing's Syndrome: An Endocrine Society Clinical Practice Guideline. J Clin Endocrinol Metab. 2015;100(8):2807-2831.",
      pmid: "26222757",
    },
    {
      citation:
        "Melmed S et al. Diagnosis and Treatment of Hyperprolactinemia: An Endocrine Society Clinical Practice Guideline. J Clin Endocrinol Metab. 2011;96(2):273-288.",
      pmid: "21296991",
    },
  ];
}

export function getRecommendationColor(rec: PrimaryRecommendation): string {
  switch (rec) {
    case "urgent_surgery":
      return "red";
    case "surgery_first":
      return "blue";
    case "medical_therapy_first":
      return "green";
    case "radiosurgery_adjuvant":
      return "purple";
    case "multidisciplinary_evaluation":
      return "orange";
    case "observation_with_imaging":
      return "gray";
    default:
      return "gray";
  }
}

export function getTumorTypeLabel(type: TumorType): string {
  switch (type) {
    case "prolactinoma":
      return "Prolactinoma (PRL-secreting)";
    case "acromegaly_gh":
      return "Acromegaly (GH-secreting)";
    case "cushings_acth":
      return "Cushing's Disease (ACTH-secreting)";
    case "tshoma":
      return "TSHoma (TSH-secreting)";
    case "nonfunctioning":
      return "Non-functioning Pituitary Adenoma";
    default:
      return type;
  }
}

export function getTumorSizeLabel(size: TumorSize): string {
  switch (size) {
    case "microadenoma":
      return "Microadenoma (<10 mm)";
    case "macroadenoma":
      return "Macroadenoma (10–40 mm)";
    case "giant":
      return "Giant Adenoma (>40 mm)";
    default:
      return size;
  }
}
